public class InvocationMatcher_captureArgumentsFrom_TriageGen2Test {

    /**
     * Interface to mock the CapturesArguments behavior since it's an interface.
     */
    private interface MockCapturesArguments extends CapturesArguments {}

    @Test
    public void testCaptureArgumentsFrom_WithNoMatchers() {
        Invocation invocation = mock(Invocation.class);
        List<Matcher> matchers = new ArrayList<>();
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);
        // Should complete without exception
    }

    @Test
    public void testCaptureArgumentsFrom_WithOnlyNonCapturingMatchers() {
        Invocation invocation = mock(Invocation.class);
        Object arg0 = "arg0";
        Object arg1 = "arg1";

        when(invocation.getArguments()).thenReturn(new Object[]{arg0, arg1});

        Matcher normalMatcher = mock(Matcher.class);
        List<Matcher> matchers = Arrays.asList(normalMatcher, normalMatcher);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);
        // Should complete without calling captureFrom on normal matchers
    }

    @Test
    public void testCaptureArgumentsFrom_WithCapturingMatchers() {
        Invocation invocation = mock(Invocation.class);
        Object arg0 = "first";
        Object arg1 = "second";
        Object arg2 = "third";

        when(invocation.getArguments()).thenReturn(new Object[]{arg0, arg1, arg2});

        MockCapturesArguments capturer0 = mock(MockCapturesArguments.class);
        Matcher normalMatcher = mock(Matcher.class);
        MockCapturesArguments capturer2 = mock(MockCapturesArguments.class);

        List<Matcher> matchers = Arrays.asList(capturer0, normalMatcher, capturer2);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        verify(capturer0).captureFrom(arg0);
        verify(capturer2).captureFrom(arg2);
    }

    @Test
    public void testCaptureArgumentsFrom_MixedMatchersCoverage() {
        // This test ensures we hit the branch where k increments regardless of whether it's a CapturesArguments
        Invocation invocation = mock(Invocation.class);
        Object[] args = new Object[]{"a", "b"};
        when(invocation.getArguments()).thenReturn(args);

        MockCapturesArguments capturer = mock(MockCapturesArguments.class);
        Matcher normal = mock(Matcher.class);

        // Order: Capturer (index 0), Normal (index 1)
        List<Matcher> matchers = Arrays.asList(capturer, normal);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        verify(capturer).captureFrom("a");
        // If k didn't increment, normal matcher would have received "a" or capturer would have received "b"
    }

